/**
 * 底部日志控制台：显示选中单元最近的日志。
 *
 * 作为页面底部的常驻面板，不覆盖卡片网格、不弹模态，切换单元只换内容。
 * 日志由页面静默轮询刷新：停在底部时自动跟随最新一行，向上翻看时保持不动。
 * 头部支持按关键词过滤（本地、大小写不敏感）与复制当前可见内容。
 */
import { useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react'
import { LOG_LEVELS, loadPrefs, savePrefs, subscribePrefs } from '../prefs.ts'
import { IconButton } from './IconButton.tsx'
import { IconCheck, IconChevronDown, IconCopy, IconPause, IconPlay, IconRefresh, IconTrash } from './primitives.ts'

export interface LogDockProps {
  /** 正在查看日志的单元名 */
  name: string
  /** 日志正文 */
  text: string
  /** 是否正在读取（手动刷新时显示转圈） */
  loading: boolean
  /** 最近一次刷新的时刻文本；空串表示还没读到 */
  readAt: string
  /** 自动刷新是否已暂停 */
  paused: boolean
  /** 当前请求的行数 */
  lines: number
  /** 立即重新读取 */
  onRefresh: () => void
  /** 暂停 / 继续自动刷新 */
  onTogglePause: () => void
  /** 切换行数（120 → 300 → 1000 循环） */
  onCycleLines: () => void
  /** 清空该单元日志（页面负责先确认） */
  onClear: () => void
  /** 收起面板 */
  onClose: () => void
}

/**
 * 渲染日志控制台。
 * @param props - 日志内容与回调
 * @returns 面板元素
 */
export function LogDock({
  name, text, loading, readAt, paused, lines, onRefresh, onTogglePause, onCycleLines, onClear, onClose,
}: LogDockProps): JSX.Element {
  const body = useRef<HTMLPreElement | null>(null)
  const follow = useRef(true)
  const [filter, setFilter] = useState('')
  const [level, setLevel] = useState(loadPrefs().logLevel)
  useEffect(() => subscribePrefs((prefs) => setLevel(prefs.logLevel)), [])
  const [copied, setCopied] = useState(false)

  const allLines = useMemo(() => text.split('\n'), [text])
  const shownLines = useMemo(() => {
    const needle = filter.trim().toLowerCase()
    const errorPattern = /error|错误|traceback|exception|critical|fatal|failed|失败/i
    const warnPattern = /warn|警告/i
    return allLines.filter((line) => {
      if (level !== 'all') {
        const isError = errorPattern.test(line)
        if (level === 'error' && !isError) return false
        if (level === 'warn' && !isError && !warnPattern.test(line)) return false
      }
      return needle === '' || line.toLowerCase().includes(needle)
    })
  }, [allLines, filter, level])
  const shown = shownLines.join('\n')
  const filtering = filter.trim() !== '' || level !== 'all'

  // 换单元时清掉过滤、重新贴到底部
  useLayoutEffect(() => {
    follow.current = true
    setFilter('')
    const element = body.current
    if (element !== null) element.scrollTop = element.scrollHeight
  }, [name])

  // 内容刷新（或过滤变化）：只有用户本来就停在底部才跟着走
  useLayoutEffect(() => {
    const element = body.current
    if (element !== null && follow.current) element.scrollTop = element.scrollHeight
  }, [shown])

  const handleScroll = (): void => {
    const element = body.current
    if (element === null) return
    follow.current = element.scrollHeight - element.scrollTop - element.clientHeight < 24
  }

  const copy = async (): Promise<void> => {
    try {
      await navigator.clipboard.writeText(shown)
      setCopied(true)
      window.setTimeout(() => setCopied(false), 1500)
    } catch {
      // 剪贴板不可用时什么都不做，避免误报「已复制」
    }
  }

  return (
    <section className="bc-dock" aria-label={`${name} 日志`}>
      <header className="bc-dock-head">
        <span className="bc-dock-title">日志</span>
        <span className="bc-dock-sub">{name}</span>
        {readAt !== '' && <span className="bc-dock-sub">· {readAt} 刷新</span>}
        <span className="bc-dock-spacer" />
        <input
          className="bc-dock-filter"
          value={filter}
          placeholder="过滤"
          aria-label="过滤日志"
          onChange={(event) => setFilter(event.target.value)}
          onKeyDown={(event) => { if (event.key === 'Escape') setFilter('') }}
        />
        <span className="bc-dock-levels" role="group" aria-label="日志级别">
          {LOG_LEVELS.map(([key, label]) => (
            <button
              key={key}
              type="button"
              className="bc-dock-level"
              data-active={level === key || undefined}
              onClick={() => { savePrefs({ logLevel: key }); setLevel(key) }}
            >
              {label}
            </button>
          ))}
        </span>
        {filtering && <span className="bc-dock-match">{shownLines.length} / {allLines.length}</span>}
        <button type="button" className="bc-dock-lines" onClick={onCycleLines} title="切换读取行数">
          {lines} 行
        </button>
        <IconButton
          label={paused ? '继续刷新' : '暂停刷新'}
          icon={paused ? IconPlay : IconPause}
          active={paused}
          onClick={onTogglePause}
        />
        <IconButton
          label={copied ? '已复制' : '复制日志'}
          icon={copied ? IconCheck : IconCopy}
          onClick={() => void copy()}
        />
        <IconButton label="清空日志" icon={IconTrash} onClick={onClear} />
        <IconButton label="立即刷新" icon={IconRefresh} busy={loading} onClick={onRefresh} />
        <IconButton label="收起日志" icon={IconChevronDown} onClick={onClose} />
      </header>
      <pre ref={body} className="bc-dock-body" onScroll={handleScroll}>{
        loading && text === ''
          ? '读取中…'
          : filtering && shownLines.length === 0 ? '（没有匹配的行）' : shown
      }</pre>
    </section>
  )
}
